{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "청년정책 사업에 기여하는 단체의 서울시 지원 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제23조제1항에 따르면 시장은 청년단체와 청년정책의 시행에 기여하는 단체 또는 기관, 청년기업 등에 행정적·재정적 지원을 할 수 있다. 따라서 청년정책 사업에 기여하는 단체는 서울시 지원을 받을 수 있다.",
          "b_ids": "청년:제23조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "경비 지원 절차를 규정하는 조례",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제23조제2항은 제1항에 따른 경비의 지원 방법·절차, 그 밖에 필요한 사항은 「서울특별시 지방보조금 관리 조례」에 따른다고 규정한다. 따라서 경비 지원 절차는 「서울특별시 지방보조금 관리 조례」를 따른다.",
          "b_ids": "청년:제23조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
